values ('bbbb0004-0000-4000-8000-000000000007', 'en', null, 'Introduction to Astronomy', 'A first tour of the universe — from the motions of the night sky and the physics of orbits to stars, galaxies, and the Big Bang. Structure adapted from OpenStax Astronomy 2e (CC BY 4.0).', null, 'foundations', 7, true, 'science', '{}')
