insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000007', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Astronomy is best described as the scientific study of…","options":["only the planets","everything beyond Earth''s atmosphere and the universe as a whole","weather patterns","Earth''s interior"],"answer":1,"explanation":"Astronomy studies celestial objects and the universe itself — see ''The nature of astronomy''."},{"prompt":"The apparent daily rising and setting of the Sun and stars is caused mainly by…","options":["the Sun orbiting Earth","Earth''s rotation on its axis","the Moon''s gravity","the tilt of Earth''s orbit"],"answer":1,"explanation":"Earth spins once a day, so the sky appears to turn — see ''Observing the sky''."},{"prompt":"Kepler''s first law states that planets orbit the Sun along paths shaped like…","options":["perfect circles","ellipses","spirals","straight lines"],"answer":1,"explanation":"Orbits are ellipses with the Sun at one focus — see ''Orbits and gravity''."},{"prompt":"The force that keeps planets in orbit around the Sun is…","options":["magnetism","gravity","the solar wind","radiation pressure"],"answer":1,"explanation":"Newton showed gravity provides the centripetal pull — see ''Orbits and gravity''."},{"prompt":"The Sun produces its energy through…","options":["burning coal or gas chemically","nuclear fusion of hydrogen into helium","friction from spinning","nuclear fission of uranium"],"answer":1,"explanation":"Fusion in the core powers the Sun — see ''The Sun: a nuclear powerhouse''."},{"prompt":"A light-year is a unit of…","options":["time","distance","brightness","mass"],"answer":1,"explanation":"It is the distance light travels in one year — see ''A tour of the universe''."},{"prompt":"Our Sun is located in a galaxy called the…","options":["Andromeda Galaxy","Milky Way","Large Magellanic Cloud","Whirlpool Galaxy"],"answer":1,"explanation":"The Sun is one of billions of stars in the Milky Way — see ''The Milky Way galaxy''."},{"prompt":"The observation that distant galaxies are moving away from us supports the idea that…","options":["the universe is shrinking","the universe is expanding","Earth is the center of the universe","galaxies are fixed in place"],"answer":1,"explanation":"Hubble''s law and cosmic expansion — see ''The Big Bang''."}]}'::jsonb, null, 10),
  (2, 'The sky and celestial motions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the sky appears to move and describe the causes of day, night, and the seasons. Warm-up: from the diagnostic, what makes the stars appear to rise in the east and set in the west?"},{"heading":"The idea","text":"The sky looks like a giant dome, the *celestial sphere*, but its apparent motion comes from Earth, not the stars. Earth''s *rotation* (one spin per day) makes the Sun and stars appear to move across the sky. Earth''s *revolution* (one orbit per year) plus its 23.5° axial *tilt* produce the seasons: when your hemisphere leans toward the Sun, sunlight strikes more directly and days are longer — that is summer."},{"heading":"Worked example","text":"In June the Northern Hemisphere tilts toward the Sun, so the Sun climbs high at noon and daylight lasts long — northern summer. At the same moment the Southern Hemisphere tilts away and has winter. The seasons are opposite because the tilt, not the distance to the Sun, is what matters. (Earth is actually slightly closer to the Sun in January.)"},{"heading":"Your turn","text":"Answer each: (1) What motion causes day and night? (2) What causes the yearly cycle of seasons? (3) True or false: summer happens because Earth is closest to the Sun. (4) If it is winter in Argentina, what season is it in Canada? Answers: (1) Earth''s rotation on its axis; (2) Earth''s revolution combined with its axial tilt; (3) false — the tilt causes seasons, not distance; (4) summer."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking seasons come from Earth being nearer or farther from the Sun (the tilt is the real cause). Mistake: confusing rotation (daily spin) with revolution (yearly orbit). Exit: (a) Which Earth motion takes one year? (b) The Sun rises in which direction? Answers: revolution; the east."}]}'::jsonb, 'Rotation = one day (spin on axis); revolution = one year (orbit around the Sun).', 12),
  (3, 'Gravity and orbits: Kepler and Newton', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State Kepler''s three laws and explain how Newton''s gravity accounts for them. Warm-up: what shape did Kepler show planetary orbits to be?"},{"heading":"The idea","text":"*Kepler''s laws*, drawn from Tycho Brahe''s data, describe planetary motion: (1) each planet moves in an *ellipse* with the Sun at one focus; (2) a planet sweeps out equal areas in equal times, so it moves faster when nearer the Sun; (3) a planet''s orbital period squared is proportional to its average distance cubed. *Newton* then explained all three with *universal gravitation*: every mass attracts every other, with a force that grows with mass and weakens with the square of the distance. The Sun''s gravity is the invisible tether curving each planet''s path into an orbit."},{"heading":"Worked example","text":"By Kepler''s third law, P² = a³ when P is in years and a in astronomical units (AU). Mars orbits at about a = 1.52 AU, so a³ ≈ 3.5 and P ≈ √3.5 ≈ 1.9 years — matching Mars''s real 1.88-year period. Newton showed that a cannonball fired fast enough simply keeps ''falling around'' Earth; that continual fall is what an orbit is."},{"heading":"Your turn","text":"Answer each: (1) What is the shape of every planet''s orbit? (2) Where in its orbit does a planet move fastest? (3) Which scientist explained WHY planets obey Kepler''s laws? (4) If a planet orbits at 4 AU, roughly what is its period (use P² = a³)? Answers: (1) an ellipse; (2) at perihelion, its closest point to the Sun; (3) Newton, with gravity; (4) a³ = 64, so P = 8 years."},{"heading":"Common mistakes & exit ticket","text":"Mistake: picturing orbits as circles — they are ellipses (usually only slightly so). Mistake: thinking gravity ''turns off'' in orbit; astronauts float because they are in continuous free fall, not because gravity is gone. Exit: (a) The Sun sits at which point of the ellipse? (b) Does gravity get stronger or weaker with distance? Answers: one focus; weaker (as the inverse square)."}]}'::jsonb, 'Kepler described HOW planets move; Newton explained WHY — gravity.', 13),
  (4, 'The solar system and its planets', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Contrast the terrestrial and giant planets and describe the Sun''s family of objects. Warm-up: name the four planets closest to the Sun."},{"heading":"The idea","text":"The solar system formed about 4.6 billion years ago from a collapsing cloud of gas and dust. The *terrestrial planets* — Mercury, Venus, Earth, Mars — are small, dense, and rocky, orbiting close to the Sun. The *giant (jovian) planets* — Jupiter, Saturn, Uranus, Neptune — are far larger, made mostly of hydrogen, helium, and ices, and ringed by many moons. Beyond Neptune lie icy bodies, including dwarf planets such as Pluto, plus asteroids and comets left over from formation."},{"heading":"Worked example","text":"Compare Earth and Jupiter. Earth is a rocky world about 12,700 km across with one moon. Jupiter is a gas giant roughly 143,000 km across — more than eleven Earths wide — with dozens of moons and no solid surface. The pattern is systematic: worlds that formed inside the ''frost line,'' where it was too warm for ices to condense, stayed small and rocky; those beyond it grew huge and gassy."},{"heading":"Your turn","text":"Classify each: (1) Mars, (2) Saturn, (3) Mercury, (4) Neptune — terrestrial or giant? And: (5) roughly how old is the solar system? Answers: (1) terrestrial; (2) giant; (3) terrestrial; (4) giant; (5) about 4.6 billion years."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming gas giants have a solid surface to stand on (they do not — the gas grows denser with depth). Mistake: thinking asteroids and comets are the same; asteroids are rocky and comets are icy. Exit: (a) Which planet type is larger, terrestrial or jovian? (b) What is Pluto now classified as? Answers: jovian (giant); a dwarf planet."}]}'::jsonb, 'Terrestrial planets = small, rocky, inner; jovian planets = large, gaseous, outer.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The seasons on Earth are caused mainly by…","options":["Earth''s changing distance from the Sun","the 23.5° tilt of Earth''s axis","the phases of the Moon","solar flares"],"answer":1,"explanation":"Axial tilt changes how directly sunlight strikes each hemisphere."},{"prompt":"Kepler''s first law says planetary orbits are…","options":["circles","ellipses","spirals","parabolas"],"answer":1,"explanation":"Ellipses with the Sun at one focus."},{"prompt":"A planet moves fastest when it is…","options":["farthest from the Sun","closest to the Sun","exactly halfway","at constant speed throughout"],"answer":1,"explanation":"Kepler''s second law — equal areas in equal times."},{"prompt":"Newton''s key contribution was showing that planetary motion is governed by…","options":["magnetism","gravity","the solar wind","friction"],"answer":1,"explanation":"Universal gravitation explains Kepler''s laws."},{"prompt":"Which is a terrestrial planet?","options":["Jupiter","Saturn","Mars","Neptune"],"answer":2,"explanation":"Mars is small and rocky; the others are giants."},{"prompt":"The astronomical unit (AU) is defined as roughly the distance between…","options":["the Earth and the Moon","the Earth and the Sun","two neighboring stars","the Sun and Jupiter"],"answer":1,"explanation":"1 AU is the average Earth-Sun distance."}]}'::jsonb, null, 8),
  (6, 'The Sun and the stars', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how stars generate energy and what a star''s color and brightness reveal. Warm-up: what process powers the Sun?"},{"heading":"The idea","text":"The Sun is an ordinary star: a vast ball of hot gas held together by its own gravity. In its core, *nuclear fusion* joins hydrogen nuclei into helium, releasing the energy that becomes sunlight. A star''s *color* tells its surface *temperature* — blue-white stars are hottest, yellow ones like the Sun are medium, and red stars are coolest. Astronomers also distinguish *luminosity* (the true energy output) from *apparent brightness* (how bright a star looks from Earth, which also depends on distance)."},{"heading":"Worked example","text":"Betelgeuse looks reddish, so its surface is relatively cool — around 3,500 K — yet it appears bright in our sky because it is a huge, highly luminous supergiant. A hot blue star like Rigel has a surface near 12,000 K. Two stars can look equally bright from Earth while having very different true luminosities: a nearby dim star and a distant brilliant one can appear the same."},{"heading":"Your turn","text":"Answer each: (1) What nuclear process powers a star? (2) Which is hotter, a blue star or a red star? (3) A star''s true energy output is called its ___. (4) Why can a very luminous star still look faint from Earth? Answers: (1) nuclear fusion of hydrogen into helium; (2) the blue star; (3) luminosity; (4) because it is very far away — apparent brightness falls off with distance."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming red means hot and blue means cool (it is the reverse for stars). Mistake: confusing how bright a star looks with how much energy it truly emits. Exit: (a) The Sun fuses hydrogen into what element? (b) Which is cooler, Betelgeuse (red) or Rigel (blue)? Answers: helium; Betelgeuse."}]}'::jsonb, 'Stars fuse hydrogen into helium; a star''s color reveals its temperature (blue = hot, red = cool).', 13),
  (7, 'How stars live and die', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace the life cycle of a star and explain how its mass determines how it ends. Warm-up: what happens when a star finally runs out of hydrogen fuel in its core?"},{"heading":"The idea","text":"Stars are born in clouds of gas and dust and spend most of their lives fusing hydrogen. When the core''s hydrogen runs low, the star swells into a *red giant*. What comes next depends on *mass*. A low-mass star like the Sun sheds its outer layers and leaves behind a dense, cooling *white dwarf*. A high-mass star fuses heavier elements until its core collapses and it explodes as a *supernova*, forging heavy elements and leaving a *neutron star* or, if massive enough, a *black hole*. The atoms in your body were made inside such stars."},{"heading":"Worked example","text":"The Sun, about 5 billion years from now, will expand into a red giant, engulf the inner planets, then puff off its outer gas and settle into a white dwarf roughly Earth-sized. A star ten times the Sun''s mass instead ends in a supernova — briefly outshining a whole galaxy — and collapses into a neutron star only about 20 km across but denser than an atomic nucleus."},{"heading":"Your turn","text":"Answer each: (1) What does a star become when its core hydrogen runs low? (2) What remnant does a Sun-like star leave? (3) What violent event ends a high-mass star''s life? (4) The heavy elements in your body were forged where? Answers: (1) a red giant; (2) a white dwarf; (3) a supernova; (4) inside stars (and in supernova explosions)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking every star ends as a black hole (only the most massive do). Mistake: assuming the Sun will explode (it is too low in mass — it becomes a white dwarf). Exit: (a) A supernova can leave behind which two kinds of remnant? (b) Will the Sun become a black hole? Answers: a neutron star or a black hole; no — a white dwarf."}]}'::jsonb, 'A star''s mass decides its fate: low-mass → white dwarf; high-mass → supernova, then neutron star or black hole.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"light-year","translation":"the distance light travels in one year, about 9.5 trillion kilometers","example":"The nearest star beyond the Sun is about four light-years away."},{"term":"orbit","translation":"the curved path one object takes around another under gravity","example":"Earth completes one orbit of the Sun each year."},{"term":"nuclear fusion","translation":"the joining of light atomic nuclei into heavier ones, releasing energy","example":"Nuclear fusion of hydrogen powers the Sun."},{"term":"luminosity","translation":"the total amount of energy a star emits per second","example":"A supergiant''s luminosity can be tens of thousands of times the Sun''s."},{"term":"supernova","translation":"the explosive death of a high-mass star","example":"A supernova can briefly outshine its entire galaxy."},{"term":"galaxy","translation":"a huge, gravitationally bound system of stars, gas, and dust","example":"The Milky Way is the galaxy that contains our solar system."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The energy of the Sun and other stars comes from…","options":["chemical burning","nuclear fusion","gravitational collapse alone","friction"],"answer":1,"explanation":"Fusion of hydrogen into helium in the core."},{"prompt":"Which color indicates the hottest star surface?","options":["red","orange","yellow","blue"],"answer":3,"explanation":"Blue-white stars are the hottest."},{"prompt":"A star like the Sun will end its life as a…","options":["black hole","white dwarf","neutron star","supernova remnant"],"answer":1,"explanation":"Low-mass stars leave white dwarfs."},{"prompt":"The explosive death of a high-mass star is a…","options":["nova","red giant","supernova","solar flare"],"answer":2,"explanation":"A supernova; it can leave a neutron star or black hole."},{"prompt":"The Milky Way is best described as…","options":["a single large star","the galaxy containing our Sun","another name for the solar system","a nearby planet"],"answer":1,"explanation":"It is our home galaxy of hundreds of billions of stars."},{"prompt":"The observation that distant galaxies recede faster the farther they are is known as…","options":["Kepler''s law","Hubble''s law","Newton''s law","the Doppler shift of the Moon"],"answer":1,"explanation":"Hubble''s law is evidence for cosmic expansion and the Big Bang."}]}'::jsonb, null, 8),
  (10, 'Applied project: build a scale model of the cosmos', 'writing', '{"sections":[{"heading":"The task","text":"Design a scale model that makes cosmic distances intuitive. You will not build it physically — you''ll plan and describe it precisely, showing you can reason quantitatively about astronomical scale."},{"heading":"Milestones","text":"1) Pick a scale where the Earth-Sun distance (1 AU) equals a convenient length, such as 1 meter. 2) On that scale, work out roughly how far away Neptune (about 30 AU) would be. 3) Explain, in words, why the nearest star (about 270,000 AU away) would be far off your model — even kilometers away. 4) Write two sentences on what this exercise reveals about how empty space is and why light-years are a useful unit."},{"heading":"Self-check rubric","text":"✔ You stated a clear, consistent scale. ✔ Your Neptune distance follows correctly from that scale (about 30 m if 1 AU = 1 m). ✔ You correctly showed the nearest star lands enormously farther away than the planets. ✔ You connected the model to why astronomers measure distance in light-years. If all four hold, you''ve grasped the true scale of the universe."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000007' and l.position = v.pos
);
